import os
import time

def build_index():
    memory_index = {}
    # Performing full system scan
    for root, dirs, files in os.walk('/'):
        # Skip special/virtual file systems to avoid hangs
        if any(skip in root for skip in ['/proc', '/sys', '/dev', '/run']):
            continue

        for file in files:
            filepath = os.path.join(root, file)
            # Only index text files / files under 50KB to prevent OOM crashes
            try:
                if not os.path.islink(filepath) and os.path.getsize(filepath) < 50 * 1024:
                    with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                        content = f.read()
                        # Simple heuristic for text content
                        if '\0' not in content:
                            memory_index[filepath] = content
            except Exception:
                pass

    return memory_index

if __name__ == '__main__':
    # Build memory-resident index
    index = build_index()
    # Keep the process alive in the background so the index remains in memory
    while True:
        time.sleep(3600)
